SELECT * FROM ads_chat_analysis
WHERE dimension_type = #{dimensionType}

    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY stat_date ASC, dimension_value ASC

SELECT * FROM ads_chat_analysis
WHERE dimension_type IN

    #{t}


    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY stat_date ASC, dimension_type ASC, dimension_value ASC

SELECT * FROM ads_chat_analysis
WHERE dimension_type = #{dimensionType}

    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY ${orderField} DESC
LIMIT #{limit}

SELECT dimension_value AS dimensionValue, SUM(session_count) AS sessionCount, SUM(user_count) AS userCount, SUM(conversion_count) AS conversionCount, ROUND(SUM(conversion_count) / SUM(session_count), 4) AS conversionRate FROM ads_chat_analysis WHERE dimension_type = 'product'
AND stat_date >= #{startDate}
AND stat_date <= #{endDate}
GROUP BY dimension_value ORDER BY sessionCount DESC LIMIT #{limit}
